  'settings.pushNote': { ru: 'Приходят даже если приложение закрыто и экран выключен: раз в день вечером — напоминание записать траты, плюс уведомления о целях и платежах.', en: "Arrive even with the app closed and the screen off: a daily evening reminder to log your spending, plus goal and bill alerts.", es: 'Llegan incluso con la app cerrada y la pantalla apagada: un recordatorio diario para registrar tus gastos, además de alertas de metas y pagos.', fr: "Arrivent même app fermée et écran éteint : un rappel quotidien pour enregistrer vos dépenses, plus des alertes objectifs et paiements." },  'settings.pushEnable': { ru: 'Включить push-уведомления', en: 'Enable push notifications', es: 'Activar notificaciones push', fr: 'Activer les notifications push' },
  'settings.digest': { ru: 'Вечерняя сводка', en: 'Evening summary', es: 'Resumen de la noche', fr: 'Bilan du soir' },
  'settings.digestNote': { ru: 'Каждый вечер: сколько потрачено от дневного лимита, какой лимит на завтра и как движется цель.', en: 'Every evening: spending against today’s limit, tomorrow’s limit, and how your goal is moving.', es: 'Cada noche: gasto frente al límite, límite de mañana y avance de la meta.', fr: 'Chaque soir : dépenses face à la limite, limite de demain et avancée de l’objectif.' },
