  'settings.pushSaveFailed': { ru: 'Не удалось сохранить подписку, попробуй ещё раз.', en: "Couldn't save the subscription, try again.", es: 'No se pudo guardar la suscripción, intenta de nuevo.', fr: "Impossible d'enregistrer l'abonnement, réessayez." },
  'settings.pushFailed': { ru: 'Не получилось включить — подожди пару секунд и нажми ещё раз.', en: "Couldn't switch it on — wait a couple of seconds and tap again.", es: 'No se pudo activar — espera unos segundos y vuelve a pulsar.', fr: "Impossible de l’activer — patientez quelques secondes et réessayez." },
