  'settings.shareText': { ru: 'Попробуй это приложение для денег — помогает копить на цели и гасить долги:', en: 'Try this money app — it helps you save for goals and pay off debt:', es: 'Prueba esta app de dinero — ayuda a ahorrar para metas y pagar deudas:', fr: "Essaie cette app pour l'argent — elle aide à épargner et à rembourser ses dettes :" },
  'settings.shareCopied': { ru: 'Ссылка скопирована — вставь её в чат', en: 'Link copied — paste it into a chat', es: 'Enlace copiado — pégalo en un chat', fr: 'Lien copié — colle-le dans une discussion' },
  'settings.data': { ru: 'Данные', en: 'Data', es: 'Datos', fr: 'Données' },
  'settings.dataNoteCloud': { ru: 'Данные синхронизируются с вашим защищённым аккаунтом в облаке, поэтому доступны с любого устройства. Видите их только вы.', en: 'Your data syncs to your secure cloud account, so it follows you across devices. Only you can see it.', es: 'Tus datos se sincronizan con tu cuenta segura en la nube, así están en todos tus dispositivos. Solo tú los ves.', fr: "Vos données sont synchronisées avec votre compte sécurisé dans le cloud et vous suivent sur tous vos appareils. Vous seul y avez accès." },
  'common.day': { ru: 'день', en: 'day', es: 'día', fr: 'jour' },
  'settings.dataNote': { ru: 'Все данные хранятся локально в этом браузере — сервера с вашими финансами нет.', en: "All data lives locally in this browser — there's no server holding your finances.", es: 'Todos los datos se guardan localmente en este navegador — no hay un servidor con tus finanzas.', fr: "Toutes les données restent locales dans ce navigateur — aucun serveur ne conserve vos finances." },
  'settings.resetData': { ru: 'Удалить все данные и выйти', en: 'Erase all data & sign out', es: 'Borrar todos los datos y salir', fr: 'Effacer les données et se déconnecter' },
  'settings.resetFailed': { ru: 'Не удалось удалить данные. Проверьте интернет и попробуйте ещё раз', en: "Couldn't erase the data. Check your connection and try again", es: 'No se pudieron borrar los datos. Revisa tu conexión e inténtalo de nuevo', fr: "Impossible d'effacer les données. Vérifiez votre connexion et réessayez" },
  'settings.resetConfirm': { ru: 'Это навсегда удалит все ваши записи, цели и настройки — и на этом устройстве, и в облаке. Продолжить?', en: 'This permanently deletes all your transactions, goals and settings, on this device and in the cloud. Continue?', es: 'Esto elimina permanentemente tus gastos, metas y ajustes en este dispositivo. ¿Continuar?', fr: 'Cela supprime définitivement vos dépenses, objectifs et paramètres sur cet appareil. Continuer ?' },
  'settings.signOut': { ru: 'Выйти из аккаунта', en: 'Sign out', es: 'Cerrar sesión', fr: 'Se déconnecter' },
  'settings.about': { ru: 'О приложении', en: 'About', es: 'Acerca de', fr: 'À propos' },
  'settings.aboutBody': { ru: 'Fintera — приложение для финансовой грамотности и учёта личных и бизнес-финансов.', en: 'Fintera — a financial literacy and personal/business budgeting app.', es: 'Fintera — una app de educación financiera y control de gastos personales/de negocio.', fr: 'Fintera — une application d\'éducation financière et de suivi budgétaire.' },

