  'goals.gapIntro': { ru: 'Пока не хватает {amt}/день до плана — это нормально на старте, вот два честных варианта:', en: "You're short {amt}/day of the plan — that's normal early on, here are two honest options:", es: 'Aún faltan {amt}/día para el plan — es normal al inicio, aquí dos opciones honestas:', fr: "Il manque {amt}/jour par rapport au plan — c'est normal au début, voici deux options honnêtes :" },
