  'path.why.starter': { ru: 'Даже небольшой запас резко снижает шанс финансового краха.', en: 'Even a small cushion sharply cuts the odds of a money crisis.', es: 'Incluso un pequeño colchón reduce mucho el riesgo de crisis.', fr: 'Même un petit coussin réduit fortement le risque de crise.' },
  'path.why.month': { ru: 'Потерянная неделя работы или поломка машины — уже не катастрофа.', en: 'A lost week of work or a car repair stops being a disaster.', es: 'Una semana sin trabajo o una avería deja de ser un desastre.', fr: 'Une semaine sans travail ou une panne ne sont plus une catastrophe.' },
  'path.why.debt': { ru: 'Всё выше 8% годовых. Начинай с самого маленького — каждая закрытая карта держит мотивацию.', en: 'Anything above 8% APR. Start with the smallest — each account closed keeps you going.', es: 'Todo lo que supere el 8% anual. Empieza por la más pequeña.', fr: 'Tout ce qui dépasse 8 % par an. Commencez par la plus petite.' },
  'path.why.threeMonths': { ru: 'Полноценная подушка: можно спокойно пережить потерю дохода.', en: 'A full cushion: you can ride out a lost income calmly.', es: 'Un colchón completo para aguantar sin ingresos.', fr: 'Un vrai coussin pour traverser une perte de revenu.' },
  'path.why.invest': { ru: '8 из 10 миллионеров назвали регулярные вложения главным фактором.', en: '8 in 10 millionaires named steady investing as the key factor.', es: '8 de cada 10 millonarios lo señalan como clave.', fr: '8 millionnaires sur 10 citent l’investissement régulier comme clé.' },
  'path.why.goals': { ru: 'Фундамент готов — теперь деньги работают на твои мечты.', en: 'The foundation is built — now money works for your dreams.', es: 'La base está lista: ahora el dinero trabaja para tus sueños.', fr: 'Les bases sont posées : l’argent travaille pour vos rêves.' },
