  'path.investNoIncome': { ru: 'Внеси доходы за месяц — посчитаем, сколько это 15%.', en: 'Log this month’s income and we’ll work out your 15%.', es: 'Registra los ingresos del mes para calcular tu 15%.', fr: 'Saisissez les revenus du mois pour calculer vos 15 %.' },
  'path.goalsNone': { ru: 'Поставь большую цель — дом, машину, свободу.', en: 'Set a big goal — a home, a car, freedom.', es: 'Fija una gran meta: casa, coche, libertad.', fr: 'Fixez un grand objectif : maison, voiture, liberté.' },
  'path.goalsCta': { ru: 'Поставить цель →', en: 'Set a goal →', es: 'Fijar una meta →', fr: 'Fixer un objectif →' },
  'path.rateLabel': { ru: 'Сначала себе: {rate}% с каждого дохода', en: 'Pay yourself first: {rate}% of every income', es: 'Págate primero: {rate}% de cada ingreso', fr: 'Payez-vous d’abord : {rate} % de chaque revenu' },
  'path.raiseOffer': { ru: 'Доход вырос — поднять «сначала себе» до {next}%? На жизнь всё равно останется больше, чем раньше.', en: 'Your income went up — raise pay-yourself-first to {next}%? You’ll still have more to live on than before.', es: 'Tus ingresos subieron: ¿subir «págate primero» al {next}%? Igual te quedará más para vivir que antes.', fr: 'Ton revenu a augmenté — passer « Payez-vous d’abord » à {next} % ? Il te restera quand même plus qu’avant pour vivre.' },
  'path.rules': { ru: 'Три правила: 1) сначала отложи себе, потом трать; 2) когда растёт доход — процент растёт на 1%, до 15%; 3) кредитку гаси полностью каждый месяц.', en: 'Three rules: 1) set your share aside first, then spend; 2) when income grows, the rate climbs 1%, up to 15%; 3) pay the card in full every month.', es: 'Tres reglas: 1) ahorra primero y luego gasta; 2) cuando suben tus ingresos, sube un 1%, hasta el 15%; 3) paga la tarjeta completa cada mes.', fr: 'Trois règles : 1) mettez de côté d’abord, dépensez ensuite ; 2) quand le revenu augmente, +1 %, jusqu’à 15 % ; 3) soldez la carte chaque mois.' },
  'entry.payFirst': { ru: 'Сначала себе: отложить {rate}% ({amt}) → {dest}', en: 'Pay yourself first: set aside {rate}% ({amt}) → {dest}', es: 'Págate primero: aparta {rate}% ({amt}) → {dest}', fr: 'Payez-vous d’abord : mettre {rate} % ({amt}) → {dest}' },
