  'path.earnMore': { ru: 'Больше зарабатывать: налоги, льготы, подработка', en: 'Earn more: taxes, benefits, side work', es: 'Ganar más: impuestos, ayudas, trabajos extra', fr: 'Gagner plus : impôts, aides, petits boulots' },
  'debts.title': { ru: 'Долги', en: 'Debts', es: 'Deudas', fr: 'Dettes' },
  'debts.subtitle': { ru: 'Порядок погашения: от самого маленького', en: 'Payoff order: smallest first', es: 'Orden de pago: de la más pequeña', fr: 'Ordre de remboursement : la plus petite d’abord' },
  'debts.total': { ru: 'Всего долгов', en: 'Total debt', es: 'Deuda total', fr: 'Dette totale' },
  'debts.summary': { ru: 'Долгов: {n} · минимальные платежи {min}/мес', en: '{n} debt(s) · minimum payments {min}/mo', es: '{n} deuda(s) · pagos mínimos {min}/mes', fr: '{n} dette(s) · minimums {min}/mois' },
  'debts.method': { ru: 'Плати минимум по всем, а всё сверху — в первый в списке. Закрыл — его платёж переходит на следующий. Сначала дорогие (от 8% годовых), среди них — самый маленький: каждая закрытая карта держит мотивацию.', en: 'Pay the minimum on all, and everything extra on the first one. Once it’s gone, its payment rolls to the next. Expensive ones (8%+ APR) first, smallest of those first — each closed account keeps you going.', es: 'Paga el mínimo en todas y todo lo extra en la primera. Cuando se cierra, su pago pasa a la siguiente. Primero las caras (8%+), y entre ellas la más pequeña.', fr: 'Payez le minimum partout et tout le surplus sur la première. Une fois soldée, son paiement passe à la suivante. D’abord les chères (8 %+), la plus petite en premier.' },
  'debts.emptyTitle': { ru: 'Долгов нет — или ещё не внесены', en: 'No debts — or none added yet', es: 'Sin deudas, o aún no añadidas', fr: 'Aucune dette — ou pas encore ajoutée' },
  'debts.emptySubtitle': { ru: 'Добавь кредитки, займы, кредит за машину — приложение покажет, какой гасить первым.', en: 'Add cards, loans, a car loan — the app will show which to pay first.', es: 'Añade tarjetas, préstamos o el del coche: verás cuál pagar primero.', fr: 'Ajoutez cartes, prêts, crédit auto : l’app montre lequel rembourser d’abord.' },
