  'debts.linkSubtitle': { ru: 'Порядок погашения и платежи', en: 'Payoff order and payments', es: 'Orden de pago y pagos', fr: 'Ordre de remboursement et paiements' },
  'earn.title': { ru: 'Больше зарабатывать', en: 'Earn more', es: 'Ganar más', fr: 'Gagner plus' },
  'earn.subtitle': { ru: 'Вторая половина системы', en: 'The other half of the system', es: 'La otra mitad del sistema', fr: 'L’autre moitié du système' },
  'earn.intro': { ru: 'Урезать траты можно только до какого-то предела, а доход можно поднимать сколько угодно. Вот конкретные шаги — от денег, которые тебе уже положены, до подработки.', en: 'Spending can only be cut so far; income has no ceiling. Concrete moves — from money you’re already owed to side work.', es: 'Los gastos solo se pueden recortar hasta cierto punto; los ingresos no tienen techo. Pasos concretos.', fr: 'On ne peut réduire les dépenses que jusqu’à un certain point ; les revenus n’ont pas de plafond. Des actions concrètes.' },
  'earn.group.tax': { ru: 'Налоги: деньги, которые уже твои', en: 'Taxes: money that’s already yours', es: 'Impuestos: dinero que ya es tuyo', fr: 'Impôts : de l’argent déjà à vous' },
