  'learn.why.dashboard': { ru: 'Где ты сейчас и что делать дальше', en: 'Where you are and what’s next', es: 'Dónde estás y qué sigue', fr: 'Où tu en es et la suite' },
  'learn.why.entry': { ru: '10 секунд на запись, свои категории', en: '10 seconds per entry, your own categories', es: '10 segundos por registro', fr: '10 secondes par saisie' },
  'learn.why.goals': { ru: 'Видеть, ради чего копишь', en: 'Keep the "why" in view', es: 'Ver para qué ahorras', fr: 'Voir pourquoi tu épargnes' },
  'learn.why.coach': { ru: 'Расскажи ситуацию — получи план', en: 'Tell your situation, get a plan', es: 'Cuenta tu situación y recibe un plan', fr: 'Raconte ta situation, reçois un plan' },
  'learn.why.debts': { ru: 'Какой гасить первым', en: 'Which to pay first', es: 'Cuál pagar primero', fr: 'Laquelle rembourser d’abord' },
