  'learn.why.lessons': { ru: '3–5 минут в день о деньгах', en: '3–5 minutes a day about money', es: '3–5 minutos al día', fr: '3–5 minutes par jour' },
  'vision.add': { ru: 'Добавить фото цели', en: 'Add a photo of your goal', es: 'Añade una foto de tu meta', fr: 'Ajouter une photo de l’objectif' },
  'vision.addHint': { ru: 'Машина, дом, мама — то, ради чего копишь. Будет на главной и в напоминаниях.', en: 'The car, the house, mom — what you’re saving for. Shown on home and in reminders.', es: 'El coche, la casa, mamá: por lo que ahorras. Se verá en inicio y en recordatorios.', fr: 'La voiture, la maison, maman : ce pour quoi vous épargnez. Affiché à l’accueil et dans les rappels.' },
  'vision.change': { ru: 'Сменить фото', en: 'Change photo', es: 'Cambiar foto', fr: 'Changer la photo' },
  'vision.uploadFailed': { ru: 'Не удалось загрузить фото — попробуй ещё раз.', en: 'Couldn’t upload the photo — try again.', es: 'No se pudo subir la foto. Inténtalo de nuevo.', fr: 'Impossible d’envoyer la photo, réessayez.' },
  'vision.weeklyOn': { ru: 'Напоминать с фото раз в неделю', en: 'Remind me with the photo once a week', es: 'Recordármelo con la foto una vez por semana', fr: 'Me le rappeler avec la photo chaque semaine' },
