  'vision.bannerLabel': { ru: 'Ради чего всё это', en: 'What it’s all for', es: 'Por qué lo haces', fr: 'Pour quoi vous le faites' },
  'vision.bannerLeft': { ru: '{pct}% · осталось {left}', en: '{pct}% · {left} to go', es: '{pct}% · faltan {left}', fr: '{pct} % · reste {left}' },
  'entry.cardRemind': { ru: 'Каждый день напоминать погасить карту, пока долг не закрыт', en: 'Remind me every day to pay the card off until it’s at zero', es: 'Recordarme cada día pagar la tarjeta hasta dejarla en cero', fr: 'Me rappeler chaque jour de solder la carte jusqu’à zéro' },
  'accounts.dailyRemind': { ru: 'Напоминать каждый день погасить', en: 'Daily reminder to pay it off', es: 'Recordatorio diario para pagarla', fr: 'Rappel quotidien pour la solder' },
  'accounts.dailyRemindOff': { ru: 'Долга нет — напоминать нечего', en: 'Nothing owed — nothing to remind', es: 'Sin deuda, nada que recordar', fr: 'Rien à payer, rien à rappeler' },
  'entry.splitOn': { ru: 'Разделить по счетам', en: 'Split across accounts', es: 'Dividir entre cuentas', fr: 'Répartir entre comptes' },
