  'entry.splitOver': { ru: 'Больше суммы на {amt}', en: '{amt} over the total', es: '{amt} más que el total', fr: '{amt} de plus que le total' },
  'entry.splitDone': { ru: 'Сходится ✓', en: 'Adds up ✓', es: 'Cuadra ✓', fr: 'Le compte est bon ✓' },
  'entry.incomeAccountHint': { ru: 'Куда пришли деньги — кэш или карта/счёт', en: 'Where the money landed — cash or a card/account', es: 'Dónde llegó el dinero — efectivo o tarjeta/cuenta', fr: "Où l'argent est arrivé — espèces ou carte/compte" },
  'bills.notifNote': { ru: 'Напоминание придёт браузерным уведомлением, только пока приложение открыто на этом устройстве — без интернет-соединения в фоне это не работает.', en: 'The reminder arrives as a browser notification, only while the app is open on this device — it can\'t fire in the background.', es: 'El recordatorio llega como notificación del navegador, solo mientras la app esté abierta en este dispositivo — no funciona en segundo plano.', fr: "Le rappel arrive sous forme de notification du navigateur, uniquement pendant que l'application est ouverte sur cet appareil — cela ne fonctionne pas en arrière-plan." },

  'radar.premiumNote': { ru: 'Сейчас радар смотрит только траты, которые ты вносишь сам. Автоматическое обнаружение по банковской карте — платная функция в будущем.', en: 'Right now the radar only looks at spending you enter yourself. Automatic detection from your bank card is a paid feature planned for later.', es: 'Por ahora el radar solo mira los gastos que registras tú mismo. La detección automática desde tu tarjeta bancaria será una función de pago más adelante.', fr: "Pour l'instant, le radar ne regarde que les dépenses que vous saisissez vous-même. La détection automatique depuis votre carte bancaire sera une fonctionnalité payante à venir." },

  'tax.entryTitle': { ru: 'Оценка налога (бета)', en: 'Tax estimate (beta)', es: 'Estimado de impuestos (beta)', fr: 'Estimation fiscale (bêta)' },
  'tax.entrySubtitle': { ru: 'Прикинуть федеральный налог на 2026 год по доходу — за пару минут', en: 'Estimate your 2026 federal tax from your income — in a couple of minutes', es: 'Estima tu impuesto federal de 2026 según tu ingreso — en un par de minutos', fr: 'Estimez votre impôt fédéral 2026 à partir de votre revenu — en quelques minutes' },
  'tax.title': { ru: 'Оценка налога', en: 'Tax estimate', es: 'Estimado de impuestos', fr: 'Estimation fiscale' },
  'tax.subtitle': { ru: 'США, федеральный налог, 2026 год', en: 'US federal tax, 2026', es: 'Impuesto federal de EE. UU., 2026', fr: 'Impôt fédéral américain, 2026' },
  'tax.disclaimerTitle': { ru: 'Прежде чем продолжить', en: 'Before you continue', es: 'Antes de continuar', fr: 'Avant de continuer' },
  'tax.disclaimerBody': { ru: 'Мы не бухгалтеры и не налоговые консультанты. Это образовательная оценка по официальным ставкам и вычетам IRS на 2026 год — не налоговая декларация и не персональная консультация. Итоговые цифры могут отличаться в зависимости от твоей реальной ситуации (штат, вычеты, кредиты и т.д.). За советом по своей декларации обратись к CPA или Enrolled Agent.', en: "We are not accountants or tax advisors. This is an educational estimate based on official 2026 IRS rates and deductions — not a tax return and not personalized advice. Your actual numbers may differ depending on your real situation (state, deductions, credits, etc). For advice on your own return, talk to a CPA or Enrolled Agent.", es: 'No somos contadores ni asesores fiscales. Esta es una estimación educativa basada en las tasas y deducciones oficiales del IRS para 2026 — no es una declaración de impuestos ni asesoría personalizada. Tus cifras reales pueden variar según tu situación (estado, deducciones, créditos, etc). Para asesoría sobre tu declaración, consulta a un CPA o Enrolled Agent.', fr: "Nous ne sommes ni comptables ni conseillers fiscaux. Il s'agit d'une estimation éducative basée sur les taux et déductions officiels de l'IRS pour 2026 — ce n'est ni une déclaration fiscale ni un conseil personnalisé. Vos chiffres réels peuvent différer selon votre situation (état, déductions, crédits, etc). Pour un conseil sur votre propre déclaration, consultez un CPA ou un Enrolled Agent." },
  'tax.disclaimerCheckbox': { ru: 'Понимаю, что это оценка, а не налоговая консультация или декларация', en: "I understand this is an estimate, not tax advice or a tax return", es: 'Entiendo que esto es un estimado, no una asesoría fiscal ni una declaración', fr: "Je comprends qu'il s'agit d'une estimation, pas d'un conseil fiscal ni d'une déclaration" },
  'tax.disclaimerContinue': { ru: 'Понимаю, продолжить', en: 'I understand, continue', es: 'Entiendo, continuar', fr: 'Je comprends, continuer' },
  'tax.filingStatus': { ru: 'Статус подачи', en: 'Filing status', es: 'Estado civil fiscal', fr: 'Statut de déclaration' },
  'tax.filingSingle': { ru: 'Одиночный (Single)', en: 'Single', es: 'Soltero(a)', fr: 'Célibataire' },
  'tax.filingMfj': { ru: 'В браке, совместно (MFJ)', en: 'Married filing jointly', es: 'Casado(a), declaración conjunta', fr: 'Marié(e), déclaration conjointe' },
  'tax.filingHoh': { ru: 'Глава семьи (HOH)', en: 'Head of household', es: 'Cabeza de familia', fr: 'Chef de famille' },
  'tax.wages': { ru: 'Зарплата по W-2 за год, $', en: 'W-2 wages this year, $', es: 'Salario W-2 anual, $', fr: 'Salaire W-2 annuel, $' },
  'tax.selfEmployment': { ru: 'Чистая прибыль бизнеса (self-employment) за год, $', en: 'Net self-employment business profit this year, $', es: 'Ganancia neta de negocio (autónomo) anual, $', fr: "Bénéfice net d'entreprise (indépendant) annuel, $" },
