  'tax.totalTax': { ru: 'Итого федеральный налог за год', en: 'Total federal tax for the year', es: 'Impuesto federal total del año', fr: "Impôt fédéral total de l'année" },
  'tax.effectiveRate': { ru: 'Эффективная ставка: {pct}% от валового дохода', en: 'Effective rate: {pct}% of gross income', es: 'Tasa efectiva: {pct}% del ingreso bruto', fr: 'Taux effectif : {pct}% du revenu brut' },
